/**
 * Protected acceptance suite: redirect snapshot row cap + built-once lookup index.
 *
 * Test files only — no src changes. The Builder starts from this head and
 * must not edit this file. Do not edit this file to make an implementation
 * pass; return corrections to its author.
 *
 * Contract under test (builder: implement exactly this):
 *
 * - `parseMappingsSnapshot` refuses a snapshot with more than SNAPSHOT_ROW_CAP
 *   rows with the existing fixed error `Invalid redirect mappings snapshot`
 *   (the same whole-snapshot refusal malformed snapshots already get — never
 *   a silent row drop, never a message that echoes row content or counts).
 * - SNAPSHOT_ROW_CAP is 1024: the bound the live `CampaignLookupCache` in the
 *   same file already enforces (`DEFAULT_MAX_ENTRIES`), so the snapshot path
 *   can hold no more rows than the live path caches.
 * - A snapshot of exactly 1024 rows and every under-cap snapshot parse
 *   byte-identically (same `Campaign[]` the current parser produces,
 *   including optional-field presence: no `label`/`disabledAt` keys when the
 *   row omits them).
 * - Snapshot lookup serves from an index built once (at construction or on
 *   first lookup): mutating the source array after the store has served a
 *   lookup cannot change later results. Lookup results are otherwise
 *   byte-identical: first/middle/last-row hits, `null` for unknown slugs.
 * - Slug validation and the null-vs-throw outage contract are unchanged:
 *   invalid slugs return `null` without touching the database, unknown slugs
 *   return `null`, and a live-store outage still throws (never a false `null`
 *   or 404).
 *
 * Synthetic fixtures only — no endpoint, database, credential or deployment
 * is contacted.
 *
 * Run: node --import ./test/cloudflare-loader.mjs --test test/redirect-snapshot-caps-acceptance.test.ts
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  DEFAULT_MAX_ENTRIES,
  parseMappingsSnapshot,
  RedirectStore,
  type DbClient,
} from "../src/redirect-store.ts";
import type { Campaign } from "../src/redirect.ts";

/** The row cap under test: the snapshot path holds at most this many rows. */
const SNAPSHOT_ROW_CAP = 1024;
/** Fixed refusal the over-cap snapshot must carry (existing message). */
const INVALID_SNAPSHOT = "Invalid redirect mappings snapshot";

function snapshotRow(i: number): Record<string, unknown> {
  const row: Record<string, unknown> = { slug: `slug-${i}`, invite_code: `code-${i}` };
  // Vary optional-field presence across rows so the exact-cap parse pins it.
  if (i % 3 === 0) {
    row.label = `label-${i}`;
    row.disabled_at = null;
  } else if (i % 3 === 1) {
    row.label = `label-${i}`;
  }
  return row;
}

function expectedCampaign(i: number): Campaign {
  const campaign: Campaign = { slug: `slug-${i}`, inviteCode: `code-${i}` };
  if (i % 3 === 0) {
    campaign.label = `label-${i}`;
    campaign.disabledAt = null;
  } else if (i % 3 === 1) {
    campaign.label = `label-${i}`;
  }
  return campaign;
}

function snapshotJson(rows: number): string {
  const out: Record<string, unknown>[] = [];
  for (let i = 0; i < rows; i++) out.push(snapshotRow(i));
  return JSON.stringify(out);
}

test("contract rationale: the snapshot cap equals the live-cache bound", () => {
  assert.equal(
    SNAPSHOT_ROW_CAP,
    DEFAULT_MAX_ENTRIES,
    "the snapshot path holds at most what the live path caches",
  );
});

test("over-cap snapshot (cap + 1 rows) refuses with the fixed invalid-snapshot error", () => {
  assert.throws(() => parseMappingsSnapshot(snapshotJson(SNAPSHOT_ROW_CAP + 1)), {
    message: INVALID_SNAPSHOT,
  });
});

test("larger over-cap snapshot refuses with exactly the fixed error, no row echo", () => {
  let message: string | undefined;
  try {
    parseMappingsSnapshot(snapshotJson(SNAPSHOT_ROW_CAP * 4));
  } catch (err) {
    assert.ok(err instanceof Error, "refusal must be an Error");
    message = err.message;
  }
  assert.equal(message, INVALID_SNAPSHOT);
  assert.ok(!message!.includes("slug-"), "refusal must not echo row content");
  assert.ok(!message!.includes("4096"), "refusal must not echo the row count");
});

test("control: exact-cap snapshot (1024 rows) parses byte-identically", () => {
  const campaigns = parseMappingsSnapshot(snapshotJson(SNAPSHOT_ROW_CAP));
  assert.equal(campaigns.length, SNAPSHOT_ROW_CAP);
  const expected: Campaign[] = [];
  for (let i = 0; i < SNAPSHOT_ROW_CAP; i++) expected.push(expectedCampaign(i));
  assert.deepStrictEqual(campaigns, expected);
});

test("control: under-cap snapshot maps optional fields byte-identically", () => {
  const campaigns = parseMappingsSnapshot(JSON.stringify([
    { slug: "full-row", invite_code: "codeFull", label: "sidebar", disabled_at: null },
    { slug: "label-only", invite_code: "codeLabel", label: "l" },
    { slug: "bare-row", invite_code: "codeBare" },
  ]));
  assert.deepStrictEqual(campaigns, [
    { slug: "full-row", inviteCode: "codeFull", label: "sidebar", disabledAt: null },
    { slug: "label-only", inviteCode: "codeLabel", label: "l" },
    { slug: "bare-row", inviteCode: "codeBare" },
  ]);
  assert.ok(!("label" in campaigns[2]!), "an omitted label stays omitted");
  assert.ok(!("disabledAt" in campaigns[1]!), "an omitted disabled_at stays omitted");
});

function exactCapStore(): { store: RedirectStore; campaigns: Campaign[] } {
  const campaigns = parseMappingsSnapshot(snapshotJson(SNAPSHOT_ROW_CAP));
  return { store: new RedirectStore(undefined, undefined, campaigns), campaigns };
}

test("control: lookup through the index is byte-identical (first/middle/last/missing)", async () => {
  const { store } = exactCapStore();
  for (const i of [0, 511, SNAPSHOT_ROW_CAP - 1]) {
    assert.deepStrictEqual(await store.lookup(`slug-${i}`), expectedCampaign(i));
  }
  assert.equal(await store.lookup("no-such-slug"), null);
  assert.equal(await store.lookup("slug-1024"), null);
});

test("snapshot index is built once: post-construction mutation cannot change lookups", async () => {
  const campaigns = parseMappingsSnapshot(JSON.stringify([
    { slug: "alpha-row", invite_code: "codeAlpha" },
    { slug: "beta-row", invite_code: "codeBeta" },
  ]));
  const store = new RedirectStore(undefined, undefined, campaigns);
  // Prime the store first, so a lazily built index is also captured here.
  assert.deepStrictEqual(await store.lookup("alpha-row"), {
    slug: "alpha-row",
    inviteCode: "codeAlpha",
  });
  campaigns.length = 0;
  campaigns.push({ slug: "intruder-row", inviteCode: "codeIntruder" });
  assert.deepStrictEqual(
    await store.lookup("alpha-row"),
    { slug: "alpha-row", inviteCode: "codeAlpha" },
    "clearing the source array must not unresolve a known slug",
  );
  assert.equal(
    await store.lookup("intruder-row"),
    null,
    "rows added after construction must not resolve",
  );
});

test("control: invalid slugs return null without touching the database", async () => {
  const { store } = exactCapStore();
  for (const slug of ["A", "x", "metrics", "has space", "a".repeat(41), "bad\nslug"]) {
    assert.equal(await store.lookup(slug), null, JSON.stringify(slug));
  }
  let connections = 0;
  const live = new RedirectStore({ connectionString: "fixture" }, async () => {
    connections++;
    throw new Error("must not connect for an invalid slug");
  });
  for (const slug of ["metrics", "x"]) {
    assert.equal(await live.lookup(slug), null, JSON.stringify(slug));
  }
  assert.equal(connections, 0);
});

test("control: live lookup honors the null-vs-throw outage contract", async () => {
  const clientWithRow: DbClient = {
    query: async () => ({
      rows: [{
        slug: "live-slug",
        invite_code: "liveCode",
        label: "live",
        disabled_at: null,
        created_at: "2026-01-01T00:00:00.000Z",
      }],
    }),
    end: async () => {},
  };
  const emptyClient: DbClient = {
    query: async () => ({ rows: [] }),
    end: async () => {},
  };
  const hit = new RedirectStore({ connectionString: "fixture" }, async () => clientWithRow);
  assert.deepStrictEqual(await hit.lookup("live-slug"), {
    slug: "live-slug",
    inviteCode: "liveCode",
    label: "live",
    disabledAt: null,
  });
  const miss = new RedirectStore({ connectionString: "fixture" }, async () => emptyClient);
  assert.equal(await miss.lookup("live-slug"), null);
  const outage = new RedirectStore({ connectionString: "fixture" }, async () => {
    throw new Error("connection refused");
  });
  await assert.rejects(outage.lookup("live-slug"), { message: "connection refused" });
});
